using Myriale.Api.Architecture; namespace Myriale.Api.Features.ModulePackages; [FeatureSlice("ModulePackages")] public static class ModulePackagesFeature { public static IServiceCollection AddModulePackagesFeature(this IServiceCollection s,IConfiguration c){s.Configure<ModulePackageOptions>(c.GetSection(ModulePackageOptions.SectionName));s.Configure<ModuleRuntimeOptions>(c.GetSection(ModuleRuntimeOptions.SectionName));s.AddScoped<IModulePackageRepository,EfModulePackageRepository>();s.AddScoped<IModulePackageCatalog,EfModulePackageCatalog>();s.AddScoped<IModulePackageArtifactStore,FileModulePackageArtifactStore>();s.AddScoped<IModulePackageResourceReader>(p=>(FileModulePackageArtifactStore)p.GetRequiredService<IModulePackageArtifactStore>());s.AddScoped<IModulePackageInspector,ModulePackageInspector>();s.AddScoped<InstallModulePackageCommand>();s.AddScoped<RescanModulePackagesCommand>();s.AddScoped<EnableModulePackageCommand>();s.AddScoped<DisableModulePackageCommand>();s.AddScoped<IModuleRuntime,DotNetModuleRuntime>();s.AddSingleton<ModuleAssemblyCache>();s.AddSingleton<ModuleRuntimeInvocationGate>();return s;} public static IEndpointRouteBuilder MapModulePackagesFeature(this IEndpointRouteBuilder e){e.MapModuleAdminEndpoints();return e;} }
